'use client';
import{jsx as _jsx}from"react/jsx-runtime";
export function AuthSsoButtons({id,providers,pendingId,style,onPress}){
return(_jsx("span",{className:"cieo cieo-auth-sso-buttons",role:"group","aria-label":"Continue with single sign-on",style:style,children:providers.map(p=>{
const pending=pendingId===p.id;
const busy=pendingId!=null;
return(_jsx("button",{type:"button",id:`${id}-${p.id}`,className:"cieo-auth-sso-button",disabled:busy,"aria-busy":pending||undefined,onClick:()=>{if(!busy)
onPress?.(p.id);},children:pending?`Connecting to ${p.label}…`:`Continue with ${p.label}`},p.id));
})}));
}
